result.llm_view:
for (int i = size / 2 - 1; i >= 0; i--) {
    int parent = i;
    while (true) {
        int left = 2 * parent + 1;
        int right = 2 * parent + 2;
        int smallest = parent;
        if (left < size && arr[left] < arr[smallest]) {
            smallest = left;
        }
        if (right < size && arr[right] < arr[smallest]) {
            smallest = right;
        }
        if (smallest == parent) {
            break;
        }
        std::swap(arr[parent], arr[smallest]);
        parent = smallest;
    }
}

